/* SPDX-License-Identifier: GPL-2.0-only
 * Included after the real native/watchdog wrappers. Stable singleton custody.
 */
#include "owned-provider.h"
int nh_native_provider_take(int *sensor_slot,dev_t sensor_device,
 int *frame_slot,const struct qc_frame_fd_identity *frame,
 int *encoder_slot,const struct qc_encoder_fd_identity *encoder)
{
 if(!sensor_slot||!frame_slot||!encoder_slot||!frame||!encoder||!sensor_device||
    !frame->device||!frame->source_instance||!frame->file_instance||
    !encoder->device||!encoder->session_identity)return CAMERA_INVALID;
 if(!native_initialized||stop||native.retirement_uncertain||source_clock.failed||
    native.watchdog.state!=QW_UNKNOWN||native.watchdog.fd<3||
    native.providers.phase!=QP_EMPTY||memory_state.ledger.initialized||
    !storage_selected||!sensor_baseline_requested||h264_p_frames!=1||width!=1280||height!=720||
    native.continuous_sensor!=-1||native.continuous_frame!=-1||native.h264_stream_fd!=-1||
    native.providers.sensor_staged!=-1||native.providers.frame_staged.fd!=-1||
    native.providers.encoder_staged.fd!=-1||native.produced_storage||native.resident_storage||
    parked_after_stop)return CAMERA_NOT_READY;
 if(*sensor_slot<3||*frame_slot<3||*encoder_slot<3||*sensor_slot==*frame_slot||
    *sensor_slot==*encoder_slot||*frame_slot==*encoder_slot||
    *sensor_slot==native.watchdog.fd||*frame_slot==native.watchdog.fd||
    *encoder_slot==native.watchdog.fd)return CAMERA_INVALID;
 /* GET-only sensor metadata; NOT I2C_SLAVE/register reads or permission. */
 struct stat sensor;
 int flags=fcntl(*sensor_slot,F_GETFL),fdflags=fcntl(*sensor_slot,F_GETFD);
 if(flags<0||fdflags<0||fstat(*sensor_slot,&sensor)||(flags&O_ACCMODE)!=O_RDWR||
    !(fdflags&FD_CLOEXEC)||!S_ISCHR(sensor.st_mode)||sensor.st_rdev!=sensor_device)
  return CAMERA_NOT_READY; /* no role moved */
 struct qp_roles *p=&native.providers;
 p->sensor_device=sensor_device;p->sensor_filesystem=sensor.st_dev;p->sensor_inode=sensor.st_ino;
 p->frame_identity=*frame;p->encoder_identity=*encoder;
 /* First helper failure leaves ALL bootstrap slots owned by bootstrap. Its
  * uncommitted reply is not exposed; no native ownership/snapshot is invented. */
 if(qc_encoder_fd_take(&p->encoder_staged,encoder_slot,&p->encoder_identity))
  return native_guard_failure();
 p->phase=QP_MOVING;p->encoder_last=p->encoder_staged.last_observed;
 p->encoder_filesystem=p->encoder_staged.node_filesystem;p->encoder_inode=p->encoder_staged.node_inode;
 if(qc_frame_fd_take(&p->frame_staged,frame_slot,&p->frame_identity))return native_guard_failure();
 p->frame_last=p->frame_staged.last_observed;
 p->frame_filesystem=p->frame_staged.node_filesystem;p->frame_inode=p->frame_staged.node_inode;
 p->sensor_staged=*sensor_slot;*sensor_slot=-1;
 /* Actual move, not alias/copy. Every destination slot is explicit -1. */
 native.continuous_sensor=p->sensor_staged;p->sensor_staged=-1;
 if(qc_frame_fd_give_back(&p->frame_staged,&native.continuous_frame)){
  p->frame_last=p->frame_staged.last_observed;return native_guard_failure();
 }
 if(qc_encoder_fd_give_back(&p->encoder_staged,&native.h264_stream_fd)){
  p->encoder_last=p->encoder_staged.last_observed;return native_guard_failure();
 }
 p->phase=QP_COMMITTED;
 /* Reobserve actual native slots after staged records became EMPTY. No role
  * pointer/qualified flag stands in for actual tuple/metadata observations. */
 return lifetime(); /* actual per-open AND original global facts, no effect */
}

/* SPDX-License-Identifier: GPL-2.0-only
 * Real observational refusals for the actual adopted descriptions, not grants.
 */
static void provider_hold(struct qc_rtsp_context *c)
{
 c->providers.phase=QP_HOLD;
 if(c->providers.frame_staged.fd>=3)c->providers.frame_staged.state=QC_FRAME_FD_HOLD;
 if(c->providers.encoder_staged.fd>=3)c->providers.encoder_staged.state=QC_ENCODER_FD_HOLD;
}
static int provider_shape(const struct qc_rtsp_context *c)
{
 return (c->providers.phase==QP_COMMITTED||c->providers.phase==QP_ACTIVE)&&
  h264_p_frames==1&&width==1280&&height==720&&
  c->continuous_sensor>=3&&c->continuous_frame>=3&&c->h264_stream_fd>=3&&
  c->providers.sensor_staged==-1&&c->providers.frame_staged.fd==-1&&
  c->providers.encoder_staged.fd==-1&&c->providers.sensor_device&&
  c->providers.frame_identity.source_instance&&c->providers.frame_identity.file_instance&&
  c->providers.encoder_identity.session_identity;
}
static int provider_node(int fd,int mode,dev_t device,dev_t filesystem,ino_t inode)
{
 struct stat st;int flags=fcntl(fd,F_GETFL),fdflags=fcntl(fd,F_GETFD);
 return fd>=3&&flags>=0&&fdflags>=0&&!fstat(fd,&st)&&(flags&O_ACCMODE)==mode&&
  (fdflags&FD_CLOEXEC)&&S_ISCHR(st.st_mode)&&st.st_rdev==device&&
  st.st_dev==filesystem&&st.st_ino==inode;
}
static int provider_store_frame(struct qc_rtsp_context *c,const struct qc_capture_receipt *q)
{
 if(!qc_receipt_header(q)||q->state>QC_RECEIPT_UNCERTAIN||q->reason>QC_STOP_CLOSE||
    q->source_instance!=c->providers.frame_identity.source_instance||
    q->file_instance!=c->providers.frame_identity.file_instance)return -1;
 c->providers.frame_last=*q;return 0;
}
static int provider_receipt_query(struct qc_rtsp_context *c,const struct qc_capture_receipt *key,
 struct qc_capture_receipt *out)
{
 if(qc_receipt_query(c->continuous_frame,key,out))return -1;
 return provider_store_frame(c,out);
}
static int provider_encoder_observe(struct qc_rtsp_context *c)
{
 struct qp_roles *p=&c->providers;
 if(!provider_node(c->h264_stream_fd,O_RDWR,p->encoder_identity.device,
                   p->encoder_filesystem,p->encoder_inode))return capture_failed(c);
 struct qc_hwenc_open_query q={0};
 if(ioctl(c->h264_stream_fd,QC_HWENC_OPEN_QUERY,&q))return capture_failed(c);
 /* Same complete query schema as imported custody. No partial reply, old global
  * sequence fallback, relation/telemetry guess or saturation uniqueness claim. */
 if(q.version!=QC_HWENC_OPEN_QUERY_VERSION||q.struct_bytes!=sizeof(q)||q.reserved||
    !q.session_identity||q.session_identity!=p->encoder_identity.session_identity||
    q.reference_frame_num>65535||q.quarantined>1||q.dma_uncertain>1||
    q.guard_poisoned>1||q.ledger_active>1)return capture_failed(c);
 switch(q.reference_relation){
 case QC_HWENC_REFERENCE_NONE:
  if(q.reference_owner_identity||q.reference_frame_num)return capture_failed(c);break;
 case QC_HWENC_REFERENCE_THIS_OPEN:
  if(q.reference_owner_identity!=q.session_identity)return capture_failed(c);break;
 case QC_HWENC_REFERENCE_OTHER_OPEN:
  if(!q.reference_owner_identity||q.reference_owner_identity==q.session_identity)return capture_failed(c);break;
 default:return capture_failed(c);
 }
 p->encoder_last=q; /* retain valid THIS/OTHER/fault snapshot BEFORE refusing */
 if(q.quarantined||q.dma_uncertain||q.guard_poisoned||q.ledger_active||
    (q.telemetry_flags&~QC_STAGE_F_SATURATED))return capture_failed(c);
 if(c->h264_stream_frames){
  if(q.reference_relation!=QC_HWENC_REFERENCE_THIS_OPEN||q.reference_frame_num!=p->codec_frame_num)
   return capture_failed(c);
 }else if(q.reference_relation!=QC_HWENC_REFERENCE_NONE)return capture_failed(c);
 return CAMERA_OK;
}
static int provider_observe(struct qc_rtsp_context *c)
{
 struct qp_roles *p=&c->providers;
 if(!provider_shape(c)||!provider_node(c->continuous_sensor,O_RDWR,p->sensor_device,
       p->sensor_filesystem,p->sensor_inode)||
    !provider_node(c->continuous_frame,O_RDONLY,p->frame_identity.device,
       p->frame_filesystem,p->frame_inode))return capture_failed(c);
 struct qc_capture_receipt bound=qc_receipt_request(NULL);
 if(ioctl(c->continuous_frame,QC_ISP_RECEIPT_BIND,&bound)||provider_store_frame(c,&bound))
  return capture_failed(c);
 if(p->phase==QP_COMMITTED){
  if(bound.generation||bound.state!=QC_RECEIPT_NONE||bound.reason||bound.stop_result||bound.stopped_ns)
   return capture_failed(c);
 }else if(!c->receipt_armed||!qc_receipt_same(&bound,&c->receipt_key)||
    bound.state!=QC_RECEIPT_ACTIVE||bound.reason||bound.stop_result||bound.stopped_ns)
  return capture_failed(c);
 return provider_encoder_observe(c);
}

/* SPDX-License-Identifier: GPL-2.0-only */
#ifndef QP_OWNED_PROVIDER_TYPES_H
#define QP_OWNED_PROVIDER_TYPES_H
#include "frame_fd_custody.h"
#include "encoder_fd_custody.h"
#include "stage-telemetry-uapi.h"
#include <sys/stat.h>
enum qp_phase {QP_EMPTY,QP_MOVING,QP_COMMITTED,QP_ACTIVE,QP_CLOSED,QP_HOLD};
struct qp_roles {
 enum qp_phase phase; /* transfer/source history, NEVER authorization */
 int sensor_staged;
 struct qc_frame_fd_custody frame_staged;
 struct qc_encoder_fd_custody encoder_staged;
 dev_t sensor_device,sensor_filesystem,frame_filesystem,encoder_filesystem;
 ino_t sensor_inode,frame_inode,encoder_inode;
 struct qc_frame_fd_identity frame_identity;
 struct qc_encoder_fd_identity encoder_identity;
 struct qc_capture_receipt frame_last;
 struct qc_hwenc_open_query encoder_last;
 struct qc_hwenc_lifetime global_last;
 uint32_t codec_frame_num;
};
#define QP_ROLES_EMPTY { .sensor_staged=-1, .frame_staged=QC_FRAME_FD_CUSTODY_EMPTY, .encoder_staged=QC_ENCODER_FD_CUSTODY_EMPTY }
#endif

/* SPDX-License-Identifier: GPL-2.0-only
 * Included AFTER the actual frozen native adapter bodies (renamed _legacy).
 * One real singleton/context, no synthetic producer or success callbacks.
 */
#include "native_watchdog.h"
_Static_assert(NH_SESSION_NS==QW_SESSION_NS,"original fixed 10s session");
static unsigned native_initialized;
static int native_guard_failure(void)
{nh_native_fence(NULL);return CAMERA_IO_ERROR;}

void nh_native_init(void)
{
 if(native_initialized){(void)native_guard_failure();return;}
 native_init_legacy();native_initialized=1;
}
int nh_native_watchdog_take(int *slot,dev_t device)
{
 if(!native_initialized||native.retirement_uncertain||source_clock.failed||
    native.continuous_sensor!=-1||native.continuous_frame!=-1||native.h264_stream_fd!=-1||
    native.encoder_hold!=-1||native.produced_storage||native.resident_storage||
    parked_after_stop||memory_state.ledger.initialized)return CAMERA_NOT_READY;
 return qw_owner_take(&native.watchdog,slot,device)?CAMERA_NOT_READY:CAMERA_OK;
}
int nh_native_memory_start(uint64_t start)
{
 /* Keep the original CAMERA_OK / CAMERA_NOT_READY API, not NH_MEM_* reasons.
  * Refuse repeats BEFORE the unchanged initializer can memset accounting. */
 if(stop||native.retirement_uncertain||source_clock.failed||native.watchdog.state==QW_HOLD){
  (void)native_guard_failure();return CAMERA_NOT_READY;
 }
 if(!native_initialized||!native_guard_present()||!storage_selected)return CAMERA_NOT_READY;
 if(memory_state.ledger.initialized||native.watchdog.session_deadline_ns)return CAMERA_NOT_READY;
 if(lifetime()){(void)native_guard_failure();return CAMERA_NOT_READY;}
 /* Bind real-clock-checked original start BEFORE setup; even failed setup cannot
  * obtain a fresh budget. UNKNOWN/future/backward/late time is not a new epoch. */
 if(qw_owner_seal_session(&native.watchdog,start)||native_memory_start_legacy(start)){
  (void)native_guard_failure();return CAMERA_NOT_READY;
 }
 return CAMERA_OK;
}
static int native_guard_begin(enum qw_phase phase)
{
 if(native_initialized&&(stop||native.retirement_uncertain||source_clock.failed))
  return native_guard_failure();
 if(!native_initialized||native.watchdog.fd<3||
    native.watchdog.state==QW_EMPTY||native.watchdog.state==QW_HOLD)
  return CAMERA_NOT_READY;
 if(!provider_shape(&native))return CAMERA_NOT_READY;
 uint64_t start=nh_native_now(NULL);
 if(start==UINT64_MAX||!memory_state.ledger.initialized||
    !native.watchdog.session_deadline_ns||
    memory_state.session_start!=native.watchdog.session_start_ns||
    start<native.watchdog.session_start_ns||start>=native.watchdog.session_deadline_ns)
  return native_guard_failure();
 /* Observe exact adopted roles/global facts BEFORE watchdog control. Charge
  * query cost to the same original outer start; legacy repeats inside guard. */
 if(lifetime())return native_guard_failure();
 if(qw_owner_begin(&native.watchdog,start,phase,native.watchdog.session_deadline_ns))
  return native_guard_failure();
 return CAMERA_OK;
}
int nh_native_next(void *context,struct camera_packet *packet,struct nh_key *key)
{
 /* Trusted caller-owned, stable, disjoint outputs, never private loan/backing. */
 if(packet)memset(packet,0,sizeof(*packet));
 if(key)memset(key,0,sizeof(*key));
 if(!packet||!key)return CAMERA_INVALID;
 /* Sticky uncertainty precedes known BUSY. No clock/FD/control/query/service
  * on the known-loan path, and no private expected/loan/custody mutation. */
 if(stop||native.retirement_uncertain||source_clock.failed||native.watchdog.state==QW_HOLD)
  return native_guard_failure();
 if(native.produced_storage||parked_after_stop)return CAMERA_BUSY;
 /* No lifetime open/query, malloc, sensor/config/capture or codec effect until
  * actual owned guard and original preparation/paid-buffer prerequisites exist. */
 if(!provider_shape(&native)||!sensor_baseline_requested||!storage_selected||!memory_state.ledger.initialized||
    !memory_state.ledger.paid[0]||!memory_state.ledger.paid[1])return CAMERA_NOT_READY;
 int result=native_guard_begin(QW_NEXT);if(result)return result;
 result=native_next_legacy(context,packet,key);
 /* The real legacy body includes BOTH lifetime calls, cancellation/receipt and
  * encoded-begin<2s checks. Its earlier inner guard closes have been removed. */
 if(result||native.retirement_uncertain||source_clock.failed||
    qw_owner_disable_boundary(&native.watchdog)){
  memset(packet,0,sizeof(*packet));memset(key,0,sizeof(*key));
  return native_guard_failure(); /* actual unreturned backing/FDs retained */
 }
 return CAMERA_OK;
}
int nh_native_release(void *context,const struct camera_packet *packet)
{
 if(!packet||!native_initialized||native.retirement_uncertain||source_clock.failed||
    qw_owner_idle_observe(&native.watchdog))return native_guard_failure();
 int result=native_release_legacy(context,packet);
 return result?native_guard_failure():CAMERA_OK;
}
static void native_retired_cpu_release(void)
{
 /* Called ONLY after original normal retirement and successful logical guard
  * disable. A failed disable keeps resident/parked backing in the actual owner. */
 if(native.resident_storage!=raw)free(native.resident_storage);
 native.resident_storage=NULL;parked_after_stop=NULL;memset(&expected,0,sizeof(expected));
}
int nh_native_retire(void *context)
{
 if(native.produced_storage)return CAMERA_BUSY; /* known held CPU loan, no effect */
 /* No invented END/ACK proof for preloaded but never-activated roles. A healthy
  * unactivated handback API is not implemented; retain custody without rearm. */
 if(native.providers.phase==QP_COMMITTED)return CAMERA_NOT_READY;
 int result=native_guard_begin(QW_RETIRE);if(result)return result;
 result=native_retire_body(context);
 if(result||native.retirement_uncertain||source_clock.failed||
    qw_owner_disable_boundary(&native.watchdog))return native_guard_failure();
 native_retired_cpu_release();
 return CAMERA_OK;
}
int nh_native_retire_held(void *context,const struct camera_packet *packet)
{
 if(native.retirement_uncertain||source_clock.failed||parked_after_stop)return native_guard_failure();
 if(packet){
  if(!native.produced_storage||packet->data!=expected.data||packet->bytes!=expected.bytes||
     packet->monotonic_ns!=expected.monotonic_ns)return native_guard_failure();
 }else if(native.produced_storage)return native_guard_failure();
 if(native.providers.phase==QP_COMMITTED)return CAMERA_NOT_READY;
 int result=native_guard_begin(QW_RETIRE);if(result)return result;
 result=native_retire_held_legacy(context,packet);
 if(result||native.retirement_uncertain||source_clock.failed||
    qw_owner_disable_boundary(&native.watchdog))return native_guard_failure();
 native_retired_cpu_release();
 return CAMERA_OK;
}
int nh_native_watchdog_give_back(int *slot)
{
 if(!native_initialized||native.retirement_uncertain||source_clock.failed||
    native.providers.sensor_staged!=-1||native.providers.frame_staged.fd!=-1||
    native.providers.encoder_staged.fd!=-1||native.providers.phase==QP_MOVING||native.providers.phase==QP_HOLD||
    native.receipt_armed||native.continuous_frame!=-1||native.continuous_sensor!=-1||
    native.h264_stream_fd!=-1||native.encoder_hold!=-1||native.produced_storage||
    native.resident_storage||parked_after_stop||native.close_unknown)return CAMERA_NOT_READY;
 return qw_owner_give_back(&native.watchdog,slot)?CAMERA_NOT_READY:CAMERA_OK;
}

/* SPDX-License-Identifier: GPL-2.0-only */
#define _POSIX_C_SOURCE 200809L
#include "watchdog_owner.h"
#include <fcntl.h>
#include <linux/watchdog.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <time.h>
#define QW_PHASE_NS UINT64_C(2000000000)

void qw_owner_fail(struct qw_owner *o)
{if(o)o->state=QW_HOLD;}
static int fail(struct qw_owner *o)
{qw_owner_fail(o);return -1;}
static int clock_read(struct qw_owner *o,uint64_t *now)
{
 struct timespec t;
 if(clock_gettime(CLOCK_MONOTONIC,&t)||t.tv_sec<0||t.tv_nsec<0||t.tv_nsec>=1000000000L||
    (uint64_t)t.tv_sec>(UINT64_MAX-(uint64_t)t.tv_nsec)/UINT64_C(1000000000))return fail(o);
 *now=(uint64_t)t.tv_sec*UINT64_C(1000000000)+(uint64_t)t.tv_nsec;
 if(*now==UINT64_MAX||*now<o->last_ns)return fail(o);
 o->last_ns=*now;return 0;
}
static int descriptor(struct qw_owner *o)
{
 struct stat st;
 if(o->fd<3)return fail(o);
 int flags=fcntl(o->fd,F_GETFL),fdflags=fcntl(o->fd,F_GETFD);
 if(flags<0||fdflags<0||fstat(o->fd,&st)||(flags&O_ACCMODE)!=O_WRONLY||
    !(fdflags&FD_CLOEXEC)||!S_ISCHR(st.st_mode)||st.st_rdev!=o->device||
    st.st_dev!=o->node_filesystem||st.st_ino!=o->node_inode)return fail(o);
 return 0;
}
int qw_owner_take(struct qw_owner *o,int *slot,dev_t device)
{
 if(!o||!slot||!device||o->fd!=-1||o->state!=QW_EMPTY||*slot<3)return -1;
 struct stat st;
 int flags=fcntl(*slot,F_GETFL),fdflags=fcntl(*slot,F_GETFD);
 if(flags<0||fdflags<0||fstat(*slot,&st)||(flags&O_ACCMODE)!=O_WRONLY||
    !(fdflags&FD_CLOEXEC)||!S_ISCHR(st.st_mode)||st.st_rdev!=device)return -1;
 *o=(struct qw_owner){.fd=*slot,.state=QW_UNKNOWN,.device=device,
  .node_filesystem=st.st_dev,.node_inode=st.st_ino};
 *slot=-1;return 0;
}
int qw_owner_seal_session(struct qw_owner *o,uint64_t start)
{
 if(!o||o->state==QW_HOLD)return -1;
 if(o->state!=QW_UNKNOWN||o->session_deadline_ns||
    start>=UINT64_MAX-QW_SESSION_NS)return fail(o);
 uint64_t now;
 if(clock_read(o,&now)||now<start||now-start>=QW_PHASE_NS)return fail(o);
 if(descriptor(o))return -1;
 if(clock_read(o,&now)||now<start||now-start>=QW_PHASE_NS)return fail(o);
 o->session_start_ns=start;o->session_deadline_ns=start+QW_SESSION_NS;
 return 0;
}
int qw_owner_check(struct qw_owner *o)
{
 if(!o||o->state==QW_HOLD)return -1;
 if(o->state!=QW_ENABLING&&o->state!=QW_ACTIVE5)return fail(o);
 uint64_t now;
 if(clock_read(o,&now)||now<o->start_ns||now-o->start_ns>=QW_PHASE_NS||
    now>=o->session_deadline_ns)return fail(o);
 if(descriptor(o))return -1;
 /* Metadata syscalls consume the SAME phase budget; re-read immediately before
  * a caller may service the watchdog, not just before descriptor inspection. */
 if(clock_read(o,&now)||now<o->start_ns||now-o->start_ns>=QW_PHASE_NS||
    now>=o->session_deadline_ns)return fail(o);
 return 0;
}
static int control(struct qw_owner *o,unsigned long command,int *value)
{
 if(qw_owner_check(o))return -1;
 if(ioctl(o->fd,command,value))return fail(o);
 return qw_owner_check(o);
}
int qw_owner_begin(struct qw_owner *o,uint64_t source_start,enum qw_phase phase,uint64_t session_deadline)
{
 if(!o||o->state==QW_HOLD)return -1;
 if((o->state!=QW_UNKNOWN&&o->state!=QW_DISABLED)||
    !o->session_deadline_ns||session_deadline!=o->session_deadline_ns||
    source_start==UINT64_MAX||source_start<o->session_start_ns||session_deadline<=source_start||
    (phase!=QW_NEXT&&phase!=QW_RETIRE))return fail(o);
 o->start_ns=source_start; /* original sealed session is never overwritten */
 o->phase=phase;o->capture_progress=0;o->state=QW_ENABLING;
 int timeout=5,option=WDIOS_ENABLECARD;
 /* SETTIMEOUT may itself ping/start inherited active hardware. Mark transition
  * unknown before the FIRST effect; do not service if phase/clock already bad. */
 if(control(o,WDIOC_SETTIMEOUT,&timeout)||timeout!=5)return fail(o);
 if(control(o,WDIOC_SETOPTIONS,&option))return -1;
 timeout=0;
 if(control(o,WDIOC_GETTIMEOUT,&timeout)||timeout!=5)return fail(o);
 o->state=QW_ACTIVE5;return 0;
}
int qw_owner_capture_progress(struct qw_owner *o)
{
 if(!o||o->state==QW_HOLD)return -1;
 if(o->state!=QW_ACTIVE5||o->phase!=QW_NEXT||o->capture_progress)return fail(o);
 int ignored=0;
 if(control(o,WDIOC_KEEPALIVE,&ignored))return -1;
 o->capture_progress=1;return 0;
}
int qw_owner_disable_boundary(struct qw_owner *o)
{
 if(!o||o->state==QW_HOLD)return -1;
 if(o->state!=QW_ACTIVE5||(o->phase==QW_NEXT&&!o->capture_progress))return fail(o);
 int option=WDIOS_DISABLECARD;
 /* Failure/time loss after the syscall leaves UNKNOWN hardware state; do NOT
  * re-enable, ping, V-close or claim the retained FD guarantees recovery. */
 if(control(o,WDIOC_SETOPTIONS,&option))return -1;
 o->state=QW_DISABLED;return 0;
}
int qw_owner_idle_observe(struct qw_owner *o)
{
 if(!o||o->state==QW_HOLD)return -1;
 if(o->state!=QW_DISABLED)return fail(o);
 uint64_t now;
 if(clock_read(o,&now))return -1;
 if(descriptor(o))return -1;
 return clock_read(o,&now);
}
int qw_owner_give_back(struct qw_owner *o,int *slot)
{
 if(!o||!slot||*slot!=-1)return -1;
 if(qw_owner_idle_observe(o))return -1;
 *slot=o->fd;*o=(struct qw_owner)QW_OWNER_EMPTY;return 0;
}

