#include "encoder-open-query.inc"
static long encoder_ioctl(struct file *file,unsigned int command,unsigned long argument)
{
 int result;
 if(command==QC_HWENC_OPEN_QUERY)return encoder_open_query(file,argument);
 if(command==QC_HWENC_LIFETIME_QUERY){
  struct qc_hwenc_lifetime query={0};
  if(mutex_lock_interruptible(&enc.lock))return -ERESTARTSYS;
  query.version=1;query.struct_bytes=sizeof(query);
  query.quarantined=enc.quarantined;query.dma_uncertain=enc.dma_uncertain;
  query.guard_poisoned=enc.guard_poisoned;query.reset_error=enc.reset_error;
  query.failed_reset_step=enc.failed_reset_step;query.fault_session=enc.fault_session;
  query.session_sequence=enc.session_sequence;query.live_bytes=qc_codec_trace()->live_bytes;
  result=copy_to_user((void __user *)argument,&query,sizeof(query))?-EFAULT:0;
  mutex_unlock(&enc.lock);return result;
 }
 if(command==QC_HWENC_STAGE_QUERY){
  struct qc_stage_query query;
  if(mutex_lock_interruptible(&enc.lock))return -ERESTARTSYS;
  if(copy_from_user(&query,(void __user *)argument,sizeof(query)))result=-EFAULT;
  else if(qc_stage_query(qc_codec_trace(),&query))result=-EINVAL;
  else result=copy_to_user((void __user *)argument,&query,sizeof(query))?-EFAULT:0;
  mutex_unlock(&enc.lock);return result;
 }
 if(command!=QC_HWENC_INFO && command!=QC_HWENC_JPEG && command!=QC_HWENC_H264_IDR && command!=QC_HWENC_H264_STREAM)return -ENOTTY;
 if(mutex_lock_interruptible(&enc.lock))return -ERESTARTSYS;
 if(enc.quarantined){mutex_unlock(&enc.lock);return -EIO;}
 enc.active_session=((struct qc_encoder_session *)file->private_data)->identity;
 qc_stage_begin(qc_codec_trace(),command==QC_HWENC_INFO?QC_STAGE_INFO:
  command==QC_HWENC_JPEG?QC_STAGE_JPEG:QC_STAGE_H264,ktime_get_ns());
 if(enc.h264_owner&&enc.h264_owner!=file){
  qc_stage_end(qc_codec_trace(),-EBUSY,0,ktime_get_ns());mutex_unlock(&enc.lock);return -EBUSY;
 }
 if(command==QC_HWENC_INFO){
  result=codec_identity();
  if(!result&&copy_to_user((void __user *)argument,&enc.info,sizeof(enc.info)))result=-EFAULT;
 }else if(command==QC_HWENC_H264_STREAM){
  struct qc_hwenc_h264_stream_job job;
  if(copy_from_user(&job,(void __user *)argument,sizeof(job)))result=-EFAULT;
  else if(job.keyframe>1)result=-EINVAL;
  else if(!job.keyframe&&!enc.h264_owner)result=-ENODATA;
  else{
   u32 num=job.keyframe?0:(enc.h264_frame_num+1)&0xffff;
   u32 ref=job.keyframe?0:enc.h264_ref_index;
   result=encode_h264(&job.frame,job.keyframe,num,ref);job.frame_num=num;
    if(copy_to_user((void __user *)argument,&job,sizeof(job))&&!enc.quarantined)result=-EFAULT;
    if(!result){enc.h264_owner=file;enc.h264_frame_num=num;enc.h264_ref_index=ref^1;
     qc_stage_owner(qc_codec_trace(),1,job.keyframe);}
    else if(!enc.quarantined)enc.h264_owner=NULL;
  }
 }else if(command==QC_HWENC_H264_IDR){
  struct qc_hwenc_h264_job job;
  if(copy_from_user(&job,(void __user *)argument,sizeof(job)))result=-EFAULT;
  else{
   result=enc.h264_owner?-EBUSY:encode_h264(&job,true,0,0);
    if(copy_to_user((void __user *)argument,&job,sizeof(job))&&!enc.quarantined)result=-EFAULT;
  }
 }else{
  struct qc_hwenc_job job;
  if(copy_from_user(&job,(void __user *)argument,sizeof(job)))result=-EFAULT;
  else{
    result=enc.h264_owner?-EBUSY:encode_jpeg(&job);
    if(copy_to_user((void __user *)argument,&job,sizeof(job))&&!enc.quarantined)result=-EFAULT;
   qc_codec_legacy_trace("qc07f-hwenc: JPEG result=%d status=%08x bytes=%u guard_errors=%u\n",result,enc.info.status,enc.info.last_bytes,enc.info.guard_errors);
  }
 }
 qc_stage_owner(qc_codec_trace(),!!enc.h264_owner,0);
 qc_stage_end(qc_codec_trace(),result,command!=QC_HWENC_INFO,ktime_get_ns());
 mutex_unlock(&enc.lock);return result;
}
static int encoder_release(struct inode *inode,struct file *file)
{
 mutex_lock(&enc.lock);
 if(enc.h264_owner==file){
  qc_stage_begin(qc_codec_trace(),QC_STAGE_END,ktime_get_ns());
  enc.h264_owner=NULL;
  qc_stage_owner(qc_codec_trace(),!!enc.h264_owner,0);
  qc_stage_end(qc_codec_trace(),0,0,ktime_get_ns());
 }
 /* File pointer must not survive release. Fault identity is a non-reused
  * numeric session, independent of this allocation and retained forever.
  * Synchronous jobs retire before returning or quarantine; no close retry.
  */
 kfree(file->private_data);file->private_data=NULL;
 mutex_unlock(&enc.lock);return 0;
}
static int encoder_open(struct inode *inode,struct file *file)
{
 struct qc_encoder_session *session;
 int result=0;
 session=kzalloc(sizeof(*session),GFP_KERNEL);if(!session)return -ENOMEM;
 mutex_lock(&enc.lock);
 if(enc.quarantined)result=-EIO;
 else if(enc.guard_poisoned)result=-EOVERFLOW;
 else if(enc.session_sequence==~(u64)0)result=-EOVERFLOW;
 else{session->identity=++enc.session_sequence;file->private_data=session;}
 mutex_unlock(&enc.lock);
 if(result)kfree(session);
 return result;

/* SPDX-License-Identifier: GPL-2.0-only
 * Included AFTER the real enc/session/trace definitions, before encoder_ioctl.
 * No mock/shadow provider. Both ioctl and final file release use enc.lock.
 */
static long encoder_open_query(struct file *file,unsigned long argument)
{
 struct qc_hwenc_open_query query={0};
 const struct qc_encoder_session *session,*reference=NULL;
 const struct qc_stage_context *trace;
 int result;
 if(mutex_lock_interruptible(&enc.lock))return -ERESTARTSYS;
 session=file->private_data;
 /* Open initializes this before publishing the FD. Its VFS reference keeps
  * the session alive through this ioctl; final release takes the same lock. */
 if(!session||!session->identity){result=-EBADF;goto out;}
 if(enc.h264_owner){
  /* Owner is cleared under this lock BEFORE its private session is freed. */
  reference=enc.h264_owner->private_data;
  if(!reference||!reference->identity){result=-EIO;goto out;}
 }
 trace=qc_codec_trace();
 /* Init installs telemetry before misc_register. No supported unload/reprobe
  * can reset the boot-lifetime session namespace or free this provider. */
 if(!trace){result=-EIO;goto out;}
 query.version=QC_HWENC_OPEN_QUERY_VERSION;query.struct_bytes=sizeof(query);
 query.session_identity=session->identity;
 if(reference){
  query.reference_owner_identity=reference->identity;
  query.reference_relation=enc.h264_owner==file?
   QC_HWENC_REFERENCE_THIS_OPEN:QC_HWENC_REFERENCE_OTHER_OPEN;
  query.reference_frame_num=enc.h264_frame_num;
 }
 query.reference_generation=trace->owner_generation;
 query.quarantined=enc.quarantined;query.dma_uncertain=enc.dma_uncertain;
 query.guard_poisoned=enc.guard_poisoned;query.telemetry_flags=trace->flags;
 query.last_dispatch_identity=enc.active_session;
 query.operation_sequence=trace->operations;
 query.last_operation_result=trace->last.result;
 query.last_operation_kind=trace->last.kind;query.ledger_active=trace->active;
 /* Fixed bounded copy only. No counter, owner, reference, reset or MMIO write;
  * failed/partial copy is EFAULT and supplies no usable snapshot to the caller. */
 result=copy_to_user((void __user *)argument,&query,sizeof(query))?-EFAULT:0;
out:
 mutex_unlock(&enc.lock);return result;
}

static int input_clean(const struct qc_capture_receipt *q)
{
 return q->version==QC_CAPTURE_RECEIPT_VERSION&&!q->reserved&&!q->reserved2&&
  !q->state&&!q->reason&&!q->stop_result&&!q->stopped_ns;
}
static int binding(const struct qc_retirement_file *f,const struct qc_capture_receipt *q)
{return q->source_instance==f->source->id&&q->file_instance==f->id;}
static void reply(const struct qc_retirement_file *f,struct qc_capture_receipt *q)
{
 memset(q,0,sizeof(*q));q->version=QC_CAPTURE_RECEIPT_VERSION;
 q->source_instance=f->source->id;q->file_instance=f->id;q->generation=f->generation;
 q->state=f->state;q->reason=f->reason;q->stop_result=f->stop_result;q->stopped_ns=f->stopped_ns;
}
int qc_retirement_ioctl(struct qc_retirement_file *f,unsigned long cmd,const struct qc_retirement_uaccess *u)
{
 struct qc_capture_receipt q;
 if(!valid(f)||!u||!u->from_user||!u->to_user)return -EINVAL;
 if(!f->open)return -EBADF;
 if(cmd!=QC_ISP_RECEIPT_BIND&&cmd!=QC_ISP_RECEIPT_ARM&&cmd!=QC_ISP_RECEIPT_QUERY&&cmd!=QC_ISP_RECEIPT_ACK)return -ENOTTY;
 if(u->from_user(u->context,&q))return -EFAULT;
 if(!input_clean(&q))return -EINVAL;
 if(cmd==QC_ISP_RECEIPT_BIND){
  if(q.source_instance||q.file_instance||q.generation)return -EINVAL;
  reply(f,&q);return u->to_user(u->context,&q)?-EFAULT:0;
 }
 if(!binding(f,&q))return -ESTALE;
 if(cmd==QC_ISP_RECEIPT_ARM){
  if(q.generation)return -EINVAL;
  if(f->state!=QC_RECEIPT_NONE||f->source->hold)return -EBUSY;
  if(f->source->next_generation==QC_U64_MAX)return -EOVERFLOW;
  __u64 generation=++f->source->next_generation; /* never recycle even on EFAULT */
   reply(f,&q);q.generation=generation;q.state=QC_RECEIPT_ARMED;
   q.reason=QC_STOP_NONE;q.stop_result=0;q.stopped_ns=0;
  /* Publish generation BEFORE any hardware begin. A bad reply must not reserve
   * the owner or run/reset hardware. Begin subsequently needs the committed ARM.
   */
  if(u->to_user(u->context,&q))return -EFAULT;
   f->generation=generation;f->state=QC_RECEIPT_ARMED;
   f->reason=QC_STOP_NONE;f->stop_result=0;f->stopped_ns=0;
   f->source->hold=f;return 0;
 }
 if(!held(f)||q.generation!=f->generation)return -ESTALE;
 if(cmd==QC_ISP_RECEIPT_QUERY){
  reply(f,&q);return u->to_user(u->context,&q)?-EFAULT:0; /* NEVER resets/consumes */
 }
 if(f->state!=QC_RECEIPT_RETIRED||f->stop_result)return -EBUSY;
 /* ACK only consumes a proven receipt. Copy-from and validation precede commit;
  * no copy-to or hardware side effect. A successor invalidates this old key.
  */
 f->source->hold=NULL;f->generation=0;f->state=QC_RECEIPT_NONE;
 f->reason=QC_STOP_NONE;f->stop_result=0;f->stopped_ns=0;return 0;
}
int qc_retirement_begin(struct qc_retirement_file *f,const struct qc_retirement_ops *ops)
{
 if(!held(f)||!f->open)return -ESTALE;
 if(!ops||!ops->begin)return -EINVAL;
 if(f->state!=QC_RECEIPT_ARMED)return -EBUSY;
 f->state=QC_RECEIPT_STARTING;
 int r=ops->begin(ops->context);
 if(r>0)r=-EIO;
 f->state=r?QC_RECEIPT_UNCERTAIN:QC_RECEIPT_ACTIVE;
 f->stop_result=r?-EINPROGRESS:0; /* no stop/reset attempt yet; never infer proof */
 return r;

int qc_retirement_stop_enter(struct qc_retirement_file *f,enum qc_capture_stop_reason reason,struct qc_retirement_fence *fence)
{
 if(!held(f))return -ESTALE;
 if(!fence)return -EINVAL;
 if(reason<QC_STOP_END||reason>QC_STOP_CLOSE)return -EINVAL;
 if(f->state!=QC_RECEIPT_ACTIVE&&f->state!=QC_RECEIPT_UNCERTAIN)return -EBUSY;
 fence->source_instance=f->source->id;fence->file_instance=f->id;fence->generation=f->generation;
 f->state=QC_RECEIPT_DRAINING;f->reason=reason;f->stopped_ns=0;return 0;
}
int qc_retirement_stop_finish(struct qc_retirement_file *f,const struct qc_retirement_fence *fence,int reset_result,__u64 now)
{
 if(!held(f)||f->state!=QC_RECEIPT_DRAINING)return -ESTALE;
 if(!fence||fence->source_instance!=f->source->id||fence->file_instance!=f->id||fence->generation!=f->generation)return -ESTALE;
 if(reset_result>0)reset_result=-EIO;
 /* This function is a PRIVATE integration callpoint, only after the entire
  * existing mask/synchronize/reset function returns, not user-supplied errno.
  * EPERM/timeout/etc can never mint success or discard the retained context.
  */
 f->stop_result=reset_result;f->state=reset_result?QC_RECEIPT_UNCERTAIN:QC_RECEIPT_RETIRED;
 f->stopped_ns=reset_result?0:now;return reset_result;
}
int qc_retirement_stop(struct qc_retirement_file *f,enum qc_capture_stop_reason why,const struct qc_retirement_ops *ops)
{
 if(!ops||!ops->stop_reset||!ops->clock_ns)return -EINVAL;
 struct qc_retirement_fence fence;int r=qc_retirement_stop_enter(f,why,&fence);if(r)return r;
 r=ops->stop_reset(ops->context);
 return qc_retirement_stop_finish(f,&fence,r,ops->clock_ns(ops->context));
}
int qc_retirement_close(struct qc_retirement_file *f,const struct qc_retirement_ops *ops)
{
 if(!valid(f)||!f->open)return -EBADF;
 int r=0;
 if(held(f)&&f->state==QC_RECEIPT_ACTIVE)r=qc_retirement_stop(f,QC_STOP_CLOSE,ops);
 else if(held(f)&&f->state!=QC_RECEIPT_ARMED&&f->state!=QC_RECEIPT_RETIRED)
  r=f->stop_result?f->stop_result:-EBUSY;
 if(r){
  f->open=0;f->source->open_files--;
  return r; /* source hold quarantines CLOSED context/backing; never free */
 }
 if(held(f))f->source->hold=NULL; /* ARMED never started; RETIRED reset proven */
 f->open=0;f->source->open_files--;return 0;
}
int qc_retirement_file_releasable(const struct qc_retirement_file *f)
{return valid(f)&&!f->open&&f->source->hold!=f;}
int qc_retirement_source_releasable(const struct qc_retirement_source *s)
{return s&&s->id&&!s->open_files&&!s->hold;}
